using System;
using System.IO;
using System.Linq;
using System.Text;
using System.Threading;
using OfficeIMO.Drawing;
using OfficeIMO.Pdf;
using OfficeIMO.Pdf.Filters;
using Xunit;

namespace OfficeIMO.Tests.Pdf;

public sealed partial class PdfRenderingResourceBoundaryTests {
    // MQ streams are generated by Build/PdfRendererQuality/jbig2.py; no timing assertion is needed.
    [Theory]
    [InlineData("AAAAAQAAAQAAADMAAAP//f8C/v7+AAAAAQAAAAGT/Lh//3//f/9//3//f/9//3//f/9//3//f/9+kkf//6w=")]
    [InlineData("AAAAAQAAAQAAADIAAAP//f8C/v7+AAAAAQAAAAGhQd//f/9//3//f/9//3//f/9//3//f/9//3//f///rA==")]
    public void NonProgressingJbig2ArithmeticIsBoundedIndependentlyOfPixels(string encoded) {
        InvalidDataException error = Assert.Throws<InvalidDataException>(() =>
            Jbig2Decoder.Decode(Convert.FromBase64String(encoded), null, 1, 1, 100000, default));
        Assert.Contains("work budget", error.Message);
    }

    [Fact]
    public void InitialZeroJbig2ExportRunRemainsLegal() {
        byte[] encoded = Convert.FromBase64String("AAAAAQAAAQAAABgAAAP//f8C/v7+AAAAAQAAAAGT/H///6w=");
        Assert.Equal(128, Assert.Single(Jbig2Decoder.Decode(encoded, null, 1, 1, 100000, default)) & 128);
    }

    [Fact]
    public void RepeatedJbig2ExportListsConsumeTheSharedStorageBudget() {
        using var source = new MemoryStream();
        byte[] dictionary = Convert.FromBase64String("AAAAAQAAAQAAABgAAAP//f8C/v7+AAAAAQAAAAGT/H///6w=");
        source.Write(dictionary, 0, dictionary.Length);
        byte[] exportBody = Convert.FromBase64String("AAAD//3/Av7+/gAAAAEAAAAAo///rA==");
        for (int number = 2; number < 240; number++) {
            WriteInt(source, number); source.WriteByte(0); source.WriteByte(32); source.WriteByte(1); source.WriteByte(1);
            WriteInt(source, exportBody.Length); source.Write(exportBody, 0, exportBody.Length);
        }
        InvalidDataException error = Assert.Throws<InvalidDataException>(() =>
            Jbig2Decoder.Decode(source.ToArray(), null, 1, 1, 200000, default));
        Assert.Contains("byte budget", error.Message);
    }

    [Fact]
    public void UnknownLengthJbig2SkipsAdaptiveBytesContainingTheTerminator() {
        byte[] encoded = Convert.FromBase64String("AAAAASYAAf////8AAAABAAAAAQAAAAAAAAAAAAD/rP3/Av7+/n///6wAAAABAAAAAjMAAQAAAAA=");
        Assert.Null(Jbig2Decoder.FindUnsupportedFeature(encoded));
        Assert.Equal(128, Assert.Single(Jbig2Decoder.Decode(encoded, null, 1, 1, 100000, default)) & 128);
    }

    [Fact]
    public void TruncatedJbig2StructuralDataCannotReadTheFollowingSegment() {
        byte[] encoded = Convert.FromBase64String("AAAAASYAAQAAABIAAAABAAAAAQAAAAAAAAAAAAAAAAACMwABAAAAAA==");
        InvalidDataException error = Assert.Throws<InvalidDataException>(() =>
            Jbig2Decoder.Decode(encoded, null, 1, 1, 100000, default));
        Assert.Contains("Truncated", error.Message);
    }

    [Fact]
    public void Jbig2DiagnosticPreflightObservesCancellation() {
        var dictionary = new PdfDictionary(); dictionary.Items["Filter"] = new PdfName("JBIG2Decode");
        var stream = new PdfStream(dictionary, Array.Empty<byte>());
        using var cancellation = new CancellationTokenSource(); cancellation.Cancel();
        Assert.Throws<OperationCanceledException>(() =>
            StreamDecoder.FindUnsupportedJbig2Feature(stream, null, 100000, cancellation.Token));
    }

    [Theory]
    [InlineData(false)]
    [InlineData(true)]
    public void Jbig2DiagnosticUsesItsOwnGlobalsAfterAnEarlierFilter(bool brokenPrefix) {
        var dictionary = new PdfDictionary();
        dictionary.Items["Filter"] = new PdfArray { Items = { new PdfName(brokenPrefix ? "FlateDecode" : "ASCIIHexDecode"), new PdfName("JBIG2Decode") } };
        var parameters = new PdfDictionary();
        // Unsupported halftone header belongs to JBIG2's second DecodeParms entry.
        parameters.Items["JBIG2Globals"] = new PdfStream(new PdfDictionary(), new byte[] { 0, 0, 0, 1, 22, 0, 1, 0, 0, 0, 0 });
        dictionary.Items["DecodeParms"] = new PdfArray { Items = { PdfNull.Instance, parameters } };
        var stream = new PdfStream(dictionary, brokenPrefix ? new byte[] { 0x78, 0x9c, 7, 0, 0, 0, 0 } : Encoding.ASCII.GetBytes(">"));
        Assert.Empty(StreamDecoder.GetUnsupportedFilters(dictionary));
        Assert.Equal(brokenPrefix ? "malformed" : "halftone", StreamDecoder.FindUnsupportedJbig2Feature(stream, null, 1024));
    }

    [Fact]
    public void Jbig2DiagnosticPrefixCannotBypassTheCallerDecodedByteLimit() {
        var dictionary = new PdfDictionary();
        dictionary.Items["Filter"] = new PdfArray { Items = { new PdfName("ASCIIHexDecode"), new PdfName("JBIG2Decode") } };
        var stream = new PdfStream(dictionary, Encoding.ASCII.GetBytes("0000>"));
        Assert.Throws<PdfReadLimitException>(() => StreamDecoder.FindUnsupportedJbig2Feature(stream, null, 1));
    }

    [Theory]
    [InlineData(100, null)]
    [InlineData(130, "filter-chain-too-long")]
    public void Jbig2DiagnosticBoundsAlternatingEmptyFilterChains(int pairCount, string? expectedFeature) {
        var dictionary = new PdfDictionary();
        var filters = new PdfArray();
        for (int index = 0; index < pairCount; index++) {
            filters.Items.Add(new PdfName("JBIG2Decode"));
            filters.Items.Add(new PdfName("RunLengthDecode"));
        }
        dictionary.Items["Filter"] = filters;
        dictionary.Items["Width"] = new PdfNumber(1);
        dictionary.Items["Height"] = new PdfNumber(4096);
        var stream = new PdfStream(dictionary, Array.Empty<byte>());

        Assert.Equal(expectedFeature, StreamDecoder.FindUnsupportedJbig2Feature(stream, null, 4096));
    }

    [Fact]
    public void Jbig2DiagnosticDoesNotDecodeTheFinalImage() {
        var dictionary = new PdfDictionary();
        dictionary.Items["Filter"] = new PdfName("JBIG2Decode");
        dictionary.Items["Width"] = new PdfNumber(1);
        dictionary.Items["Height"] = new PdfNumber(4096);
        var stream = new PdfStream(dictionary, Array.Empty<byte>());

        // Header inspection is legal even when the actual bitmap exceeds this decode limit.
        Assert.Null(StreamDecoder.FindUnsupportedJbig2Feature(stream, null, maximumBytes: 1));
    }

    [Theory]
    [InlineData(1, "exclamsmall", 33)]
    [InlineData(2, "dollaroldstyle", 36)]
    public void PredefinedCffExpertCharsetsAndEncodingSelectTheCorrectGlyph(int charset, string glyph, int code) {
        PdfCffFontProgram font = Assert.IsType<PdfCffFontProgram>(PdfCffFontProgram.TryParse(PredefinedCff(charset, 3)));
        Assert.Equal(glyph, font.GlyphNames![2]);
        Assert.Equal(2, font.BuiltinEncoding[code]);
    }

    [Fact]
    public void InvalidCffCharsetCardinalityAndOverflowAreRejected() {
        Assert.Null(PdfCffFontProgram.TryParse(PredefinedCff(0, 230)));
        Assert.Null(PdfCffFontProgram.TryParse(PredefinedCff(1, 167)));
        Assert.Throws<InvalidDataException>(() =>
            OfficeCffCharset.ReadSids(new byte[] { 0, 0, 0, 1, 255, 255, 1 }, 0, 7, 3, 3));
    }

    private static byte[] PredefinedCff(int charset, int glyphs) {
        byte[] names = Index(new[] { Encoding.ASCII.GetBytes("Expert") });
        byte[] top = { 29, 0, 0, 0, 0, 15, 29, 0, 0, 0, 0, 17, 140, 16 };
        SetInt(top, 1, charset);
        SetInt(top, 7, 4 + names.Length + Index(new[] { top }).Length + 4);
        return new byte[] { 1, 0, 4, 4 }.Concat(names).Concat(Index(new[] { top }))
            .Concat(new byte[4]).Concat(Index(Enumerable.Range(0, glyphs).Select(_ => new byte[] { 14 }).ToArray())).ToArray();
    }
}
